import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ParticleMode {
  NEBULA = 'NEBULA',
  TEXT = 'TEXT',
  HEART = 'HEART'
}

export interface GestureState {
  isPalmOpen: boolean;
  isFist: boolean;
}

export interface ParticleConfig {
  count: number;
  colors: string[];
}

import { create } from 'zustand';
import { ParticleMode } from './types';

interface AppState {
  started: boolean;
  setStarted: (started: boolean) => void;
  mode: ParticleMode;
  setMode: (mode: ParticleMode) => void;
  gestureStatus: {
    welcome: boolean;
    heart: boolean;
  };
  setGestureStatus: (status: { welcome: boolean; heart: boolean }) => void;
}

export const useStore = create<AppState>((set) => ({
  started: false,
  setStarted: (started) => set({ started }),
  mode: ParticleMode.NEBULA,
  setMode: (mode) => set({ mode }),
  gestureStatus: { welcome: false, heart: false },
  setGestureStatus: (status) => set({ gestureStatus: status }),
}));

import * as THREE from 'three';

// Sample points from text using an offscreen canvas
// This avoids needing heavy 3D font files and supports all characters including Chinese
export const createTextTargets = (text: string, count: number): Float32Array => {
  const canvas = document.createElement('canvas');
  const size = 1024; // Canvas resolution
  canvas.width = size;
  canvas.height = size / 2; // Aspect ratio for line of text
  const ctx = canvas.getContext('2d');

  if (!ctx) return new Float32Array(count * 3);

  // Draw background
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw text
  ctx.font = 'bold 120px "Noto Serif SC", serif';
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, canvas.width / 2, canvas.height / 2);

  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imageData.data;
  const validPixels: number[] = [];

  // Scan for white pixels
  for (let i = 0; i < canvas.height; i += 2) { // Skip lines for performance
    for (let j = 0; j < canvas.width; j += 2) {
      const index = (i * canvas.width + j) * 4;
      // If pixel is bright enough
      if (data[index] > 128) {
        validPixels.push(j, i);
      }
    }
  }

  const positions = new Float32Array(count * 3);

  // Map pixels to 3D space
  for (let i = 0; i < count; i++) {
    if (validPixels.length === 0) {
      positions[i * 3] = (Math.random() - 0.5) * 10;
      positions[i * 3 + 1] = (Math.random() - 0.5) * 10;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 10;
      continue;
    }

    // Pick a random valid pixel
    const pixelIndex = Math.floor(Math.random() * (validPixels.length / 2)) * 2;
    const px = validPixels[pixelIndex];
    const py = validPixels[pixelIndex + 1];

    // Normalize to 3D world coordinates
    // Canvas x (0 to size) -> World x (-15 to 15)
    // Canvas y (0 to size/2) -> World y (7.5 to -7.5)

    const x = (px / canvas.width - 0.5) * 30;
    const y = -(py / canvas.height - 0.5) * 15; 
    const z = (Math.random() - 0.5) * 1; // Slight depth

    positions[i * 3] = x;
    positions[i * 3 + 1] = y;
    positions[i * 3 + 2] = z;
  }

  return positions;
};

// Parametric Heart Shape
export const createHeartTargets = (count: number): Float32Array => {
  const positions = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    const t = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI * 2; // For volume

    // Heart formula
    // x = 16sin^3(t)
    // y = 13cos(t) - 5cos(2t) - 2cos(3t) - cos(4t)

    // Scale down to fit screen (approx / 1.5)
    const scale = 0.5;

    // Add volume
    const r = 2 * Math.sqrt(Math.random()); // Random internal radius
    const volumeX = r * Math.cos(phi);
    const volumeZ = r * Math.sin(phi);

    let x = 16 * Math.pow(Math.sin(t), 3);
    let y = 13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t);

    // Mix the parametric curve with some internal volume for a "full" heart
    x = (x + volumeX) * scale;
    y = (y + volumeX * 0.2) * scale; // slight distortion for volume
    let z = volumeZ * 2; // Z thickness

    positions[i * 3] = x;
    positions[i * 3 + 1] = y + 2; // Lift it up slightly
    positions[i * 3 + 2] = z;
  }
  return positions;
};

// Nebula / Random Sphere
export const createNebulaTargets = (count: number): Float32Array => {
  const positions = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    const radius = 15 + Math.random() * 10;
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos((Math.random() * 2) - 1);

    positions[i * 3] = radius * Math.sin(phi) * Math.cos(theta);
    positions[i * 3 + 1] = radius * Math.sin(phi) * Math.sin(theta);
    positions[i * 3 + 2] = radius * Math.cos(phi);
  }
  return positions;
};

import React, { useMemo, useRef, useEffect } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { useStore } from '../store';
import { ParticleMode } from '../types';
import { createTextTargets, createHeartTargets, createNebulaTargets } from '../utils/geometry';

const COUNT = 5000;
const DURATION = 0.8; // Animation smoothing speed

// Colors: Gold, Ruby Red, Emerald Green
const COLORS = [
  new THREE.Color('#FFD700'), // Gold
  new THREE.Color('#E0115F'), // Ruby
  new THREE.Color('#50C878'), // Emerald
  new THREE.Color('#FF4500'), // Orange-Red (for warmth)
];

const Particles: React.FC = () => {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const mode = useStore((state) => state.mode);

  // Calculate target positions for each mode once
  const targets = useMemo(() => {
    return {
      [ParticleMode.NEBULA]: createNebulaTargets(COUNT),
      [ParticleMode.TEXT]: createTextTargets("欢迎各位老师莅临听课", COUNT),
      [ParticleMode.HEART]: createHeartTargets(COUNT),
    };
  }, []);

  // Store current positions and rotation speeds
  const particles = useMemo(() => {
    const currentPositions = new Float32Array(COUNT * 3);
    const rotationSpeeds = new Float32Array(COUNT * 3);
    const colors = new Float32Array(COUNT * 3);

    // Initialize random positions
    for (let i = 0; i < COUNT; i++) {
      currentPositions[i * 3] = (Math.random() - 0.5) * 50;
      currentPositions[i * 3 + 1] = (Math.random() - 0.5) * 50;
      currentPositions[i * 3 + 2] = (Math.random() - 0.5) * 50;

      rotationSpeeds[i * 3] = (Math.random() - 0.5) * 0.02;
      rotationSpeeds[i * 3 + 1] = (Math.random() - 0.5) * 0.02;
      rotationSpeeds[i * 3 + 2] = (Math.random() - 0.5) * 0.02;

      // Assign random color from palette
      const color = COLORS[Math.floor(Math.random() * COLORS.length)];

      // Bias colors based on mode? No, kept static for jewel effect, 
      // but we could tween colors too. For now static mixed gems looks good.
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }
    return { currentPositions, rotationSpeeds, colors };
  }, []);

  // Apply colors to instance
  useEffect(() => {
    if (meshRef.current) {
      const dummy = new THREE.Object3D();
      for (let i = 0; i < COUNT; i++) {
        meshRef.current.setColorAt(i, new THREE.Color(
          particles.colors[i*3],
          particles.colors[i*3+1],
          particles.colors[i*3+2]
        ));
      }
      meshRef.current.instanceColor!.needsUpdate = true;
    }
  }, [particles]);


  const dummy = useMemo(() => new THREE.Object3D(), []);

  useFrame((state) => {
    if (!meshRef.current) return;

    const targetPositions = targets[mode];
    const time = state.clock.getElapsedTime();

    for (let i = 0; i < COUNT; i++) {
      const ix = i * 3;
      const iy = i * 3 + 1;
      const iz = i * 3 + 2;

      // Lerp current position to target
      particles.currentPositions[ix] += (targetPositions[ix] - particles.currentPositions[ix]) * (0.05 + Math.random() * 0.05);
      particles.currentPositions[iy] += (targetPositions[iy] - particles.currentPositions[iy]) * (0.05 + Math.random() * 0.05);
      particles.currentPositions[iz] += (targetPositions[iz] - particles.currentPositions[iz]) * (0.05 + Math.random() * 0.05);

      // Add floating noise
      const noise = Math.sin(time + i) * 0.05;

      dummy.position.set(
        particles.currentPositions[ix] + noise,
        particles.currentPositions[iy] + noise,
        particles.currentPositions[iz]
      );

      // Rotation
      dummy.rotation.set(
        dummy.rotation.x + particles.rotationSpeeds[ix],
        dummy.rotation.y + particles.rotationSpeeds[iy],
        dummy.rotation.z + particles.rotationSpeeds[iz]
      );

      // Scaling for transition effect
      // If heart mode, maybe scale up slightly
      const scale = mode === ParticleMode.HEART ? 1.2 : 0.8;
      dummy.scale.setScalar(scale);

      dummy.updateMatrix();
      meshRef.current.setMatrixAt(i, dummy.matrix);
    }
    meshRef.current.instanceMatrix.needsUpdate = true;
  });

  return (
    <instancedMesh ref={meshRef} args={[undefined, undefined, COUNT]}>
      {/* Small Dodecahedron for a jewel/gem look */}
      <dodecahedronGeometry args={[0.15, 0]} />
      <meshPhysicalMaterial 
        roughness={0.2}
        metalness={0.8}
        emissive="#333"
        emissiveIntensity={0.5}
        toneMapped={false}
      />
    </instancedMesh>
  );
};

export default Particles;

import React, { Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { EffectComposer, Bloom } from '@react-three/postprocessing';
import { OrbitControls } from '@react-three/drei';
import Particles from './Particles';

const ThreeScene: React.FC = () => {
  return (
    <div className="w-full h-screen absolute top-0 left-0 -z-10 bg-black">
      <Canvas
        camera={{ position: [0, 0, 25], fov: 45 }}
        dpr={[1, 2]} // Optimize pixel ratio
        gl={{ antialias: false, alpha: false }} // Performance optimizations
      >
        <color attach="background" args={['#000000']} />

        {/* Lights */}
        <ambientLight intensity={0.5} />
        <pointLight position={[10, 10, 10]} intensity={1} color="#fff" />
        <pointLight position={[-10, -10, -10]} intensity={1} color="#ff0000" />

        <Suspense fallback={null}>
          <Particles />
        </Suspense>

        {/* Post Processing for the Glow Effect */}
        <EffectComposer disableNormalPass>
          <Bloom 
            luminanceThreshold={0.2} 
            mipmapBlur 
            intensity={1.5} 
            radius={0.6}
          />
        </EffectComposer>

        {/* Subtle controls for debugging or exploration, but limited */}
        <OrbitControls 
          enableZoom={false} 
          enablePan={false} 
          maxPolarAngle={Math.PI / 1.5} 
          minPolarAngle={Math.PI / 3}
          autoRotate={true}
          autoRotateSpeed={0.5}
        />
      </Canvas>
    </div>
  );
};

export default ThreeScene;

import React, { useEffect, useRef, useState } from 'react';
import { useStore } from '../store';
import { ParticleMode } from '../types';

declare global {
  interface Window {
    Hands: any;
    Camera: any;
    drawConnectors: any;
    drawLandmarks: any;
    HAND_CONNECTIONS: any;
  }
}

const HandTracker: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { setMode, setGestureStatus } = useStore();
  const [cameraPermission, setCameraPermission] = useState(false);

  useEffect(() => {
    if (!videoRef.current || !canvasRef.current) return;

    const videoElement = videoRef.current;
    const canvasElement = canvasRef.current;
    const canvasCtx = canvasElement.getContext('2d');

    const onResults = (results: any) => {
      if (!canvasCtx) return;

      // Draw MediaPipe overlay
      canvasCtx.save();
      canvasCtx.clearRect(0, 0, canvasElement.width, canvasElement.height);
      canvasCtx.drawImage(results.image, 0, 0, canvasElement.width, canvasElement.height);

      let isWelcome = false;
      let isHeart = false;

      if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
        for (const landmarks of results.multiHandLandmarks) {
          window.drawConnectors(canvasCtx, landmarks, window.HAND_CONNECTIONS, {
            color: '#00FF00',
            lineWidth: 2,
          });
          window.drawLandmarks(canvasCtx, landmarks, {
            color: '#FF0000',
            lineWidth: 1,
            radius: 3
          });

          // --- Gesture Detection Logic ---
          // 1. Is Palm Open? (Welcome)
          // Simple heuristic: Are finger tips significantly above finger PIP joints?
          // And fingers are spread out?

          // Thumb is tricky, check index, middle, ring, pinky
          const isFingerExtended = (idx: number) => {
             // Landmark 0 is wrist. 
             // Compare tip (idx) with PIP (idx-2) distance from wrist(0)
             // Simply: Tip is further from wrist than PIP
             // Actually MediaPipe coordinates: y increases downwards.
             // So if tip.y < pip.y (assuming hand is up), it's extended. 
             // But hand can be rotated.
             // Use distance logic.

             // Simple logic: Is tip further from wrist than pip?
             const wrist = landmarks[0];
             const tip = landmarks[idx];
             const pip = landmarks[idx - 2];

             const distTip = Math.hypot(tip.x - wrist.x, tip.y - wrist.y);
             const distPip = Math.hypot(pip.x - wrist.x, pip.y - wrist.y);
             return distTip > distPip;
          };

          const indexExt = isFingerExtended(8);
          const middleExt = isFingerExtended(12);
          const ringExt = isFingerExtended(16);
          const pinkyExt = isFingerExtended(20);
          const thumbExt = isFingerExtended(4); // Rough check

          const extendedCount = [indexExt, middleExt, ringExt, pinkyExt, thumbExt].filter(Boolean).length;

          // Open Palm: At least 4 fingers extended
          if (extendedCount >= 4) {
            isWelcome = true;
          } 
          // Closed Fist: Less than 2 fingers extended
          else if (extendedCount <= 1) {
            isHeart = true;
          }
        }
      }
      canvasCtx.restore();

      // Update State
      setGestureStatus({ welcome: isWelcome, heart: isHeart });

      if (isWelcome) {
        setMode(ParticleMode.TEXT);
      } else if (isHeart) {
        setMode(ParticleMode.HEART);
      } else {
        setMode(ParticleMode.NEBULA);
      }
    };

    // Initialize MediaPipe Hands
    const hands = new window.Hands({
      locateFile: (file: string) => {
        return `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`;
      },
    });

    hands.setOptions({
      maxNumHands: 1,
      modelComplexity: 1,
      minDetectionConfidence: 0.5,
      minTrackingConfidence: 0.5,
    });

    hands.onResults(onResults);

    // Initialize Camera
    const camera = new window.Camera(videoElement, {
      onFrame: async () => {
        await hands.send({ image: videoElement });
      },
      width: 320,
      height: 240,
    });

    camera.start()
      .then(() => setCameraPermission(true))
      .catch((err: any) => console.error("Camera error:", err));

    return () => {
      // Cleanup not easily available in vanilla Camera utils wrapper, 
      // but essential to stop updates if component unmounts
      // We can rely on React unmounting to clear references.
    };
  }, [setMode, setGestureStatus]);

  return (
    <div className="relative w-48 h-36 border border-gray-700 bg-black/50 rounded-lg overflow-hidden shadow-lg backdrop-blur-sm">
       {/* Hidden video source */}
       <video 
         ref={videoRef} 
         className="hidden" 
         playsInline 
       />
       {/* Visible debug canvas */}
       <canvas 
         ref={canvasRef} 
         width={320} 
         height={240} 
         className="w-full h-full object-cover transform -scale-x-100" // Mirror effect
       />
       {!cameraPermission && (
         <div className="absolute inset-0 flex items-center justify-center text-xs text-white bg-black/80">
           Initializing Camera...
         </div>
       )}
       <div className="absolute bottom-1 left-1 text-[10px] text-gray-400">
         MediaPipe Tracking
       </div>
    </div>
  );
};

export default HandTracker;

