                    </div>
                  </div>
                </div>
              ))}
            </div>

            <button onClick={() => onBatchConfirmed(previewRooms)} className="w-full mt-4 py-3 bg-blue-600 text-white rounded-lg font-bold shadow-lg flex-shrink-0">
              确认生成全部
            </button>
          </>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { safeGetStorage, calculateBillPeriod, formatDateStr } from './utils';
import { STORAGE_KEY_CONFIG, STORAGE_KEY_DATA, DEFAULT_CONFIG } from './constants';
import { Room, AppConfig, HistoryState, ActionHandlers, ModalState, InstallPromptEvent } from './types';

// Components
import { RoomListView } from './components/RoomListView';
import { RoomEditView } from './components/RoomEditView';
import { UserGuideView } from './components/UserGuideView';
import { AddRoomModal } from './components/AddRoomModal';
import { SettingsModal } from './components/SettingsModal';
import { HistoryModal } from './components/HistoryModal';
import { BillPreviewModal } from './components/BillPreviewModal';
import { NewMonthModal } from './components/NewMonthModal';
import { BatchDateModal } from './components/BatchDateModal';
import { GenericConfirmModal } from './components/GenericConfirmModal';
import { MoveOutModal } from './components/MoveOutModal';
import { BatchBillModal } from './components/BatchBillModal';

export default function App() {
  // --- Core State ---
  const [history, setHistory] = useState<HistoryState>({ archives: [], present: [] });
  const [isLoaded, setIsLoaded] = useState(false);
  const [view, setView] = useState<'list' | 'edit' | 'add' | 'settings' | 'guide'>('list');
  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);

  // Search & Filter
  const [searchInput, setSearchInput] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [activeBuilding, setActiveBuilding] = useState('all');
  const [activeDateTab, setActiveDateTab] = useState('all');

  // Batch Selection
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal State
  const [modal, setModal] = useState<ModalState>({ type: null });

  // Config State
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);

  // PWA Install Prompt State
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);

  // --- Initialization ---
  useEffect(() => {
    try {
      const savedConfig = safeGetStorage(STORAGE_KEY_CONFIG, null);
      if (savedConfig) setConfig(savedConfig);

      let initialRooms = safeGetStorage<Room[]>(STORAGE_KEY_DATA, []);
      if (!initialRooms || initialRooms.length === 0) {
        // Migration support for older versions if needed
        initialRooms = safeGetStorage('landlord_data_v21_fresh', []); 
      }
      if (!Array.isArray(initialRooms)) initialRooms = [];

      setHistory({
        archives: [{ data: initialRooms, desc: '初始状态', time: new Date().toISOString() }],
        present: initialRooms
      });

      if (initialRooms.length === 0) setView('guide');
      setIsLoaded(true);
    } catch (e) {
      setIsLoaded(true);
    }

    // Capture PWA install prompt
    const handler = (e: Event) => {
      // Prevent the mini-infobar from appearing on mobile
      e.preventDefault();
      // Stash the event so it can be triggered later.
      setInstallPrompt(e as InstallPromptEvent);
    };

    window.addEventListener('beforeinstallprompt', handler);

    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // --- Auto Save ---
  useEffect(() => {
    if (isLoaded && history.present) {
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(history.present));
    }
  }, [history.present, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [config, isLoaded]);

  // --- Handlers ---

  const commitChange = (newRooms: Room[], desc: string) => {
    setHistory(curr => ({
      archives: [{ data: newRooms, desc, time: new Date().toISOString() }, ...curr.archives].slice(0, 50),
      present: newRooms
    }));
  };

  const handleRestore = (index: number) => {
    const target = history.archives[index];
    if (target) {
      commitChange(target.data, `恢复至: ${target.desc}`);
      setModal({ type: null });
    }
  };

  const handleInstallApp = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  const createRoomObj = (data: Partial<Room>, index = 0): Room => {
    const payDay = typeof data.payDay === 'number' ? data.payDay : 1;
    // Calculate initial dates based on payDay
    const { start, end } = calculateBillPeriod(payDay);

    return {
      id: `${Date.now()}-${index}-${Math.random().toString(36).slice(2, 6)}`,
      roomNo: data.roomNo || '未命名',
      rent: data.rent || config.defaultRent,
      deposit: data.deposit || '',
      payDay: payDay,
      tenantName: '',
      tenantPhone: '',
      fixedElecPrice: data.fixedElecPrice || '',
      fixedWaterPrice: data.fixedWaterPrice || '',
      elecPrev: 0,
      elecCurr: '',
      waterPrev: 0,
      waterCurr: '',
      extraFees: [],
      status: 'unpaid',
      lastUpdated: new Date().toISOString(),
      billStartDate: start,
      billEndDate: end
    };
  };

  const actions: ActionHandlers = {
    addRoom: (data) => {
      if (history.present.some(r => r.roomNo === data.roomNo)) return alert("房间号已存在");
      commitChange([...history.present, createRoomObj(data)], `添加 ${data.roomNo}`);
      setView('list');
    },

    batchAddConfirmed: (previewRooms) => {
      const uniqueRooms = previewRooms.filter(n => !history.present.some(o => o.roomNo === n.roomNo));
      if (uniqueRooms.length === 0) return alert("没有生成新房间(可能全部已存在)");
      const newItems = uniqueRooms.map((d, i) => createRoomObj(d, i));
      commitChange([...history.present, ...newItems], `批量生成 ${newItems.length} 间`);
      setView('list');
    },

    updateRoom: (id, data) => {
      setHistory(curr => ({
        ...curr,
        present: curr.present.map(r => r.id === id ? { ...r, ...data } : r)
      }));
    },

    saveRoom: (id, data) => {
      commitChange(
        history.present.map(r => r.id === id ? { ...r, ...data } : r),
        "更新房间信息"
      );
    },

    deleteSingle: (id) => {
      commitChange(history.present.filter(r => r.id !== id), "删除房间");
      setView('list');
      setModal({ type: null });
    },

    deleteBatch: () => {
      commitChange(
        history.present.filter(r => !selectedIds.has(r.id)),
        `批量删除 ${selectedIds.size} 项`
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
    },

    updateBatchDate: (day) => {
      commitChange(
        history.present.map(r => selectedIds.has(r.id) ? { ...r, payDay: parseInt(day) } : r),
        "批量修改日期"
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
      setActiveDateTab('all');
    },

    newMonth: (targetDay) => {
      const updated = history.present.map(r => {
        if (targetDay !== 'all' && r.payDay !== targetDay) return r;

        // Use calculateBillPeriod to shift dates:
        // Pass r.billEndDate as the 'lastEndDate' so the new start = old end.
        const { start, end } = calculateBillPeriod(r.payDay || 1, r.billEndDate);

        return {
          ...r,
          elecPrev: r.elecCurr ? parseFloat(r.elecCurr) : r.elecPrev,
          elecCurr: '',
          waterPrev: r.waterCurr ? parseFloat(r.waterCurr) : r.waterPrev,
          waterCurr: '',
          status: 'unpaid' as const,
          billStartDate: start,
          billEndDate: end
        };
      });
      commitChange(updated, "开启新月份");
      setModal({ type: null });
    },

    moveOut: (id, returnDeposit) => {
      const target = history.present.find(r => r.id === id);
      if (!target) return;

      const updated: Room = { 
        ...target, 
        deposit: returnDeposit ? '0' : target.deposit, 
        tenantName: '',
        tenantPhone: '',
        status: 'unpaid', 
        extraFees: [] 
      };

      commitChange(
        history.present.map(r => r.id === id ? updated : r), 
        `房间 ${target.roomNo} 退租`
      );
      setModal({ type: null });
      setView('list');
    }
  };

  const handleSearch = () => setActiveSearch(searchInput);
  const clearSearch = () => { setSearchInput(''); setActiveSearch(''); };

  const confirmAction = (title: string, content: string, action: () => void) => {
    setModal({ type: 'genericConfirm', title, content, onConfirm: action });
  };

  if (!isLoaded) return <div className="flex h-screen items-center justify-center text-gray-500">正在启动...</div>;

  return (
    <div className="min-h-screen bg-[#F5F7FA] font-sans text-[#1A1A1A]">
      {view === 'list' && (
        <RoomListView
          rooms={history.present}
          search={{ input: searchInput, setInput: setSearchInput, active: activeSearch, run: handleSearch, clear: clearSearch }}
          filter={{ building: activeBuilding, setBuilding: setActiveBuilding, date: activeDateTab, setDate: setActiveDateTab }}
          batch={{ isMode: isSelectionMode, setMode: setIsSelectionMode, ids: selectedIds, setIds: setSelectedIds }}
          actions={actions}
          openSettings={() => setView('settings')}
          openGuide={() => setView('guide')}
          navigate={(v, id) => { setView(v); if (id) setActiveRoomId(id); }}
          setModal={setModal}
          confirmAction={confirmAction}
          config={config}
          installPrompt={installPrompt}
          onInstall={handleInstallApp}
        />
      )}

      {view === 'edit' && activeRoomId && (
        <RoomEditView
          room={history.present.find(r => r.id === activeRoomId)}
          config={config}
          actions={actions}
          onBack={() => setView('list')}
          setModal={setModal}
          confirmAction={confirmAction}
        />
      )}

      {view === 'guide' && <UserGuideView onClose={() => setView('list')} />}

      {view === 'add' && (
        <AddRoomModal 
          config={config} 
          onSave={actions.addRoom} 
          onBatchConfirmed={actions.batchAddConfirmed} 
          onCancel={() => setView('list')} 
          confirmAction={confirmAction} 
        />
      )}

      {view === 'settings' && (
        <SettingsModal config={config} setConfig={setConfig} onClose={() => setView('list')} />
      )}

      {/* Modals */}
      {modal.type === 'history' && (
        <HistoryModal archives={history.archives} onRestore={handleRestore} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'bill' && modal.data && (
        <BillPreviewModal room={modal.data} config={config} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'batchBill' && modal.data && (
        <BatchBillModal 
          rooms={history.present.filter(r => modal.data.includes(r.id)).sort((a,b) => a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }))} 
          config={config} 
          onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'moveOut' && modal.data && (
        <MoveOutModal 
          room={modal.data} 
          config={config} 
          onConfirm={actions.moveOut} 
          onCancel={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'newMonth' && (
        <NewMonthModal rooms={history.present} onAction={actions.newMonth} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'batchDate' && (
        <BatchDateModal count={selectedIds.size} onConfirm={actions.updateBatchDate} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'genericConfirm' && modal.onConfirm && (
        <GenericConfirmModal
          title={modal.title}
          content={modal.content}
          onConfirm={() => { modal.onConfirm!(); setModal({ type: null }); }}
          onCancel={() => setModal({ type: null })}
        />
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { X, FileText, Download } from 'lucide-react';
import { Room, AppConfig } from '../types';
import { calculateBillPeriod } from '../utils';

interface BillPreviewModalProps {
  room: Room;
  config: AppConfig;
  onClose: () => void;
}

export const BillPreviewModal: React.FC<BillPreviewModalProps> = ({ room, config, onClose }) => {
  const [mode, setMode] = useState<'text' | 'image'>('text');
  const [imgSrc, setImgSrc] = useState<string | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Dates
  const [startDate] = useState(() => {
    if (room.billStartDate) return room.billStartDate;
    const { start } = calculateBillPeriod(room.payDay || 1);
    return start;
  });

  const [endDate] = useState(() => {
    if (room.billEndDate) return room.billEndDate;
    // Recalculate end based on start to ensure they align if start was just generated
    if (!room.billStartDate) {
         const { end } = calculateBillPeriod(room.payDay || 1);
         return end;
    }
    // Fallback if only start date existed in room (unlikely)
    const start = new Date(room.billStartDate);
    const end = new Date(start);
    end.setMonth(end.getMonth() + 1);
    return `${end.getFullYear()}-${String(end.getMonth() + 1).padStart(2, '0')}-${String(end.getDate()).padStart(2, '0')}`;
  });

  const getVal = (v: string | number | undefined) => parseFloat(String(v)) || 0;

  const ePrev = getVal(room.elecPrev);
  const eCurr = getVal(room.elecCurr);
  const eUsage = eCurr - ePrev;
  const ePrice = getVal(room.fixedElecPrice || config.elecPrice);
  const eTotal = Math.max(0, eUsage * ePrice);
  const hasElec = eUsage > 0 || room.elecCurr !== '';

  const wPrev = getVal(room.waterPrev);
  const wCurr = getVal(room.waterCurr);
  const wUsage = wCurr - wPrev;
  const wPrice = getVal(room.fixedWaterPrice || config.waterPrice);
  const wTotal = Math.max(0, wUsage * wPrice);
  const hasWater = wUsage > 0 || room.waterCurr !== '';

  const xTotal = (room.extraFees || []).reduce((s, i) => s + getVal(i.amount), 0);
  const total = getVal(room.rent) + eTotal + wTotal + xTotal;
  const depositVal = getVal(room.deposit);

  const dateStr = useMemo(() => {
    if (!startDate || !endDate) return '';
    const formatFull = (s: string) => {
        const [y, m, d] = s.split('-');
        return `${y}年${parseInt(m)}月${parseInt(d)}日`;
    };
    return `${formatFull(startDate)} 至 ${formatFull(endDate)}`;
  }, [startDate, endDate]);

  // Text Content
  const textContent = `【房租收据】\n日期：${dateStr}\n` + 
    `----------------\n` +
    `🏠 房号：${room.roomNo}\n` + 
    (room.tenantName ? `👤 租客：${room.tenantName}\n` : '') + 
    `💰 房租：${room.rent}元\n` + 
    (hasElec ? `⚡ 电费：${eTotal.toFixed(1)}元\n   读数：${ePrev} → ${eCurr}\n   计算：${eUsage.toFixed(1)}度 × ${ePrice}元\n` : '') + 
    (hasWater ? `💧 水费：${wTotal.toFixed(1)}元\n   读数：${wPrev} → ${wCurr}\n   计算：${wUsage.toFixed(1)}吨 × ${wPrice}元\n` : '') + 
    (room.extraFees || []).map(f => getVal(f.amount) > 0 ? `🧾 ${f.name}：${f.amount}元\n` : '').join('') + 
    `----------------\n` + 
    `💵 总计：${total.toFixed(1)} 元\n` +
    (depositVal > 0 ? `(已收押金：${depositVal}元)\n` : '');

  useEffect(() => {
    if (mode === 'image' && canvasRef.current && dateStr) {
      const ctx = canvasRef.current.getContext('2d');
      if (!ctx) return;

      // --- 1. Layout Calculation ---
      const PADDING_TOP = 160;
      const LINE_HEIGHT = 60; // Standard row height
      const READING_HEIGHT = 40; // Height for reading/calc sub-rows
      const TOTAL_BLOCK_HEIGHT = 120;
      const FOOTER_HEIGHT = 60;

      let h = PADDING_TOP;

      h += LINE_HEIGHT; // Room No
      if (room.tenantName) h += LINE_HEIGHT; // Tenant
      h += LINE_HEIGHT; // Rent (Separate Line)

      if (hasElec) {
        h += LINE_HEIGHT; // Elec Money
        h += READING_HEIGHT * 2; // Reading + Calc
        h += 10; // Extra padding
      }

      if (hasWater) {
        h += LINE_HEIGHT; // Water Money
        h += READING_HEIGHT * 2; // Reading + Calc
        h += 10;
      }

      if (room.extraFees) h += (room.extraFees.length * LINE_HEIGHT);

      h += TOTAL_BLOCK_HEIGHT;
      if (depositVal > 0) h += 40;
      h += FOOTER_HEIGHT;

      const width = 600;
      const height = h;

      canvasRef.current.width = width;
      canvasRef.current.height = height;

      // --- 2. Drawing ---

      // Background
      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, width, height);

      // Header
      ctx.fillStyle = '#2563EB';
      ctx.fillRect(0, 0, width, 16);

      ctx.fillStyle = '#111827';
      ctx.font = 'bold 36px "PingFang SC", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('房 屋 租 金 收 据', width / 2, 80);

      ctx.font = '22px "PingFang SC", sans-serif';
      ctx.fillStyle = '#6B7280';
      ctx.fillText(dateStr, width / 2, 120);

      ctx.beginPath();
      ctx.moveTo(40, 140);
      ctx.lineTo(width - 40, 140);
      ctx.strokeStyle = '#E5E7EB';
      ctx.lineWidth = 2;
      ctx.stroke();

      let y = 200; // Start Y
      ctx.textAlign = 'left';

      // Standard Row Function
      const drawLine = (icon: string, label: string, value: string, isBoldValue = true) => {
        ctx.font = '26px "PingFang SC", sans-serif';
        ctx.fillStyle = '#374151'; // Dark Gray
        ctx.fillText(`${icon} ${label}`, 40, y);

        if (value) {
            ctx.textAlign = 'right';
            ctx.font = isBoldValue ? 'bold 28px "PingFang SC", sans-serif' : '26px "PingFang SC", sans-serif';
            ctx.fillStyle = '#111827'; // Black
            ctx.fillText(value, width - 40, y);
            ctx.textAlign = 'left';
        }
        y += LINE_HEIGHT;
      };

      // --- Content Drawing ---

      // 1. Room
      drawLine('🏠', `房号：${room.roomNo}`, '');

      // 2. Tenant (Own Line, No duplicate on right)
      if (room.tenantName) {
        drawLine('👤', `租客：${room.tenantName}`, '');
      }

      // 3. Rent (Own Line)
      drawLine('💰', '房租', `¥${room.rent}`);

      // 4. Elec
      if (hasElec) {
        drawLine('⚡', '电费', `¥${eTotal.toFixed(1)}`);

        // Manual detail drawing for better spacing
        y -= 25; // Tuck up under the main line slightly
        ctx.font = '20px "PingFang SC", sans-serif';
        ctx.fillStyle = '#9CA3AF';

        ctx.fillText(`读数：${ePrev} → ${eCurr}`, 75, y);
        y += 32; // Gap between Reading and Calculation

        ctx.fillText(`计算：${eUsage.toFixed(1)}度 × ${ePrice}元`, 75, y);
        y += 35; // Gap before next section
      }

      // 5. Water
      if (hasWater) {
        drawLine('💧', '水费', `¥${wTotal.toFixed(1)}`);

        y -= 25; 
        ctx.font = '20px "PingFang SC", sans-serif';
        ctx.fillStyle = '#9CA3AF';

        ctx.fillText(`读数：${wPrev} → ${wCurr}`, 75, y);
        y += 32;

        ctx.fillText(`计算：${wUsage.toFixed(1)}吨 × ${wPrice}元`, 75, y);
        y += 35;
      }

      // 6. Extras
      if (room.extraFees) {
        room.extraFees.forEach(f => {
          if (getVal(f.amount) > 0 || f.name) {
             drawLine('🧾', f.name || '杂费', `¥${f.amount}`);
          }
        });
      }

      // Total Box
      y += 10;
      ctx.fillStyle = '#FEF2F2';
      ctx.fillRect(30, y, width - 60, 90);

      y += 55;
      ctx.fillStyle = '#DC2626';
      ctx.font = 'bold 32px "PingFang SC", sans-serif';
      ctx.fillText('总计应收', 60, y);

      ctx.textAlign = 'right';
      ctx.font = 'bold 40px "PingFang SC", sans-serif';
      ctx.fillText(`¥${total.toFixed(1)}`, width - 60, y);

      y += 60;

      if (depositVal > 0) {
        y += 10;
        ctx.font = '22px "PingFang SC", sans-serif';
        ctx.fillStyle = '#6B7280';
        ctx.textAlign = 'right';
        ctx.fillText(`(已收押金: ¥${depositVal})`, width - 40, y);
        y += 40;
      }

      // Footer
      y += 30;
      ctx.textAlign = 'center';
      ctx.font = '18px "PingFang SC", sans-serif';
      ctx.fillStyle = '#9CA3AF';
      ctx.fillText('感谢您的配合，请及时转账', width / 2, y);

      setImgSrc(canvasRef.current.toDataURL("image/png"));
    }
  }, [mode, room, config, dateStr, eTotal, eUsage, total, wTotal, wUsage, ePrev, eCurr, wPrev, wCurr, depositVal, hasElec, hasWater, ePrice, wPrice]);

  const downloadImage = () => {
    if (imgSrc) {
        const link = document.createElement('a');
        link.download = `收据_${room.roomNo}_${dateStr}.png`;
        link.href = imgSrc;
        link.click();
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 z-[100]">
      <div className="bg-white w-full max-w-md rounded-2xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
        <div className="flex justify-between items-center mb-4">
          <h3 className="font-bold text-xl flex items-center gap-2">
            <FileText className="text-blue-600"/> 账单预览
          </h3>
          <button onClick={onClose}><X size={20} className="text-gray-400"/></button>
        </div>

        <div className="flex bg-gray-100 p-1 rounded-lg mb-4 flex-shrink-0">
          <button onClick={() => setMode('text')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${mode === 'text' ? 'bg-white shadow text-black' : 'text-gray-500'}`}>
            📝 纯文本
          </button>
          <button onClick={() => setMode('image')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${mode === 'image' ? 'bg-white shadow text-blue-600' : 'text-gray-500'}`}>
            🖼️ 正式图片
          </button>
        </div>

        <div className="flex-1 overflow-y-auto bg-gray-50 rounded-xl border border-gray-200 p-4 mb-4 flex justify-center">
          {mode === 'text' ? (
            <textarea 
              className="w-full h-64 bg-transparent resize-none outline-none text-sm font-mono text-gray-700 whitespace-pre-wrap" 
              value={textContent} 
              readOnly
            />
          ) : (
            <div className="w-full flex flex-col items-center">
              <canvas ref={canvasRef} className="hidden" />
              {imgSrc ? (
                  <img src={imgSrc} alt="Bill" className="w-full h-auto rounded shadow-lg border border-gray-100" />
              ) : (
                  <div className="text-gray-400">正在生成...</div>
              )}
              <p className="text-xs text-gray-400 mt-2">长按图片可保存，或点击下方按钮</p>
            </div>
          )}
        </div>

        {mode === 'text' ? (
            <button 
              onClick={() => navigator.clipboard.writeText(textContent).then(() => alert("文本已复制"))} 
              className="w-full py-3 rounded-xl font-bold text-white shadow-md transition-colors bg-black"
            >
              复制文本
            </button>
        ) : (
            <button 
              onClick={downloadImage} 
              className="w-full py-3 rounded-xl font-bold text-white shadow-md transition-colors bg-blue-600 flex items-center justify-center gap-2"
            >
              <Download size={18} /> 保存到相册
            </button>
        )}
      </div>
    </div>
  );
};

